const { randomInt } = require("crypto");
const Otp = require("../models/Otp");

// OTPs are generated by this backend and stored in MongoDB so verification
// works across separate serverless requests and deployments. No SMS provider.
async function sendOtp(phone) {
  const normalizedPhone = String(phone || "").trim();
  if (!normalizedPhone) throw new Error("Phone number is required.");

  const code = String(randomInt(1000, 10000));
  const expiresAt = new Date(Date.now() + 5 * 60 * 1000);

  await Otp.findOneAndUpdate(
    { phone: normalizedPhone },
    { $set: { code, expiresAt } },
    { upsert: true, new: true, setDefaultsOnInsert: true }
  );

  // Demo/college-project flow: show the backend-generated code in the UI.
  // For real public use, deliver the code through a verified messaging channel.
  console.log("[BACKEND OTP GENERATED]", normalizedPhone);
  return { demo: true, code, expiresInSeconds: 300 };
}

async function checkOtp(phone, code) {
  const normalizedPhone = String(phone || "").trim();
  const enteredCode = String(code || "").trim();
  if (!normalizedPhone || !enteredCode) return false;

  const record = await Otp.findOne({ phone: normalizedPhone });
  if (!record || record.expiresAt.getTime() <= Date.now()) {
    if (record) await Otp.deleteOne({ _id: record._id });
    return false;
  }

  if (record.code !== enteredCode) return false;

  await Otp.deleteOne({ _id: record._id });
  return true;
}

module.exports = { sendOtp, checkOtp };
